package com.travelbird.ai.service;
import com.travelbird.common.enums.*;
import static org.assertj.core.api.Assertions.assertThat;import static org.mockito.Mockito.*;
import com.travelbird.ai.dto.internal.AiCallbackRequest;import com.travelbird.ai.entity.*;import com.travelbird.ai.repository.*;import com.travelbird.place.repository.PlaceRepository;import com.travelbird.trip.entity.*;import java.time.*;import java.util.*;import org.junit.jupiter.api.Test;
class AiCallbackServiceTest {
 @Test void lateCompletedAfterTimeoutIsIdempotentAndDoesNotPersistPreview(){var jobs=mock(AiRecommendationJobRepository.class);var previews=mock(AiTripPreviewRepository.class);var persistence=mock(AiPreviewPersistenceService.class);var job=mock(AiRecommendationJob.class);when(jobs.findByIdForUpdate(7L)).thenReturn(Optional.of(job));when(job.getId()).thenReturn(7L);when(job.getStatus()).thenReturn(BackendAiJobStatus.FAILED);when(previews.findByJobId(7L)).thenReturn(Optional.empty());var service=new AiCallbackService(jobs,previews,persistence,mock(AiJobTransitionService.class),mock(AiPreviewRouteValidator.class),mock(RecommendationSnapshotCodec.class),mock(PlaceRepository.class),Clock.fixed(Instant.parse("2026-09-12T00:00:00Z"),ZoneOffset.UTC));var response=service.handle(new AiCallbackRequest(7L,"COMPLETED",null,null,null,null,null,null,null,null,null));assertThat(response.accepted()).isTrue();assertThat(response.previewId()).isNull();verifyNoInteractions(persistence);}
 @Test void failedCallbackPreservesNonEnumCodeAndMessage(){var now=LocalDateTime.of(2026,9,12,12,0);var job=AiRecommendationJob.queued(7L,null,null,AiRequestType.GENERAL,"11110",LocalDate.of(2026,10,1),LocalDate.of(2026,10,1),CompanionType.SOLO,Pace.NORMAL,"[]","[]","[]","[]",true,now);job.start(now);var jobs=mock(AiRecommendationJobRepository.class);when(jobs.findByIdForUpdate(7L)).thenReturn(Optional.of(job));var service=new AiCallbackService(jobs,mock(AiTripPreviewRepository.class),mock(AiPreviewPersistenceService.class),mock(AiJobTransitionService.class),mock(AiPreviewRouteValidator.class),mock(RecommendationSnapshotCodec.class),mock(PlaceRepository.class),Clock.fixed(now.toInstant(ZoneOffset.UTC),ZoneOffset.UTC));service.handle(new AiCallbackRequest(7L,"FAILED",null,null,null,null,null,"MODEL_CAPACITY_EXCEEDED","AI model capacity exceeded",OffsetDateTime.now(ZoneOffset.UTC),Map.of("attempt",3)));assertThat(job.getErrorCode()).isEqualTo("MODEL_CAPACITY_EXCEEDED");assertThat(job.getErrorMessage()).isEqualTo("AI model capacity exceeded");}
}
